import Foundation

// Shared interfaces for every slice of the menu bar app. Owned by the orchestrator: slices build
// on these and do not edit this file.

// MARK: - Identifiers (CONTRACT.md "Apple identifiers")

enum AppIdentifiers {
    static let bundleID = "dev.drover.menubar"
    static let mainAppBundleID = "dev.drover.macos"
    static let appGroup = "group.dev.drover"
    static let keychainService = "dev.drover.token"
    /// Info.plist key holding `$(AppIdentifierPrefix)dev.drover.shared`, expanded at build time.
    static let keychainAccessGroupInfoKey = "DroverKeychainAccessGroup"
    static let urlScheme = "drover"
    /// App Group defaults key the widgets read the base URL from (CONTRACT.md widget handoff).
    static let sharedBaseURLKey = "drover.baseURL"
    /// `<App Group container>/summary.json`: bare `native.summary` result, written atomically.
    static let summaryCacheFile = "summary.json"
    /// The daemon's real SSE route (CONTRACT.md: `/api/events` is not served).
    static let ssePath = "/api/stream"
    /// The events the menu bar needs (`?topics=`): the light summary, alerts and the manager's stream and turns.
    static let streamTopics = ["summary", "alerts", "manager", "turn"]
    /// The actor this app writes as: the generic one of the owner's own clients, which the daemon records as its
    /// configured owner (`DROVER_OWNER`).
    static let actor = "owner"
    /// Whether `who` is the owner: the generic actor, or `owner`, the name the latest `native.summary` gave (a daemon
    /// from before that field gives none). Case-insensitive, as the daemon compares them.
    static func isOwner(_ who: String, owner: String?) -> Bool {
        let w = who.lowercased()
        return w == actor || (owner.map { !$0.isEmpty && w == $0.lowercased() } ?? false)
    }
    /// The OpenClaw fleet manager's session id.
    static let managerID = "manager"
}

// MARK: - Tokens

/// Raw value is the Keychain account name.
enum TokenKind: String, Sendable, CaseIterable {
    /// Full access: SSE, replies, quick actions.
    case main
    /// Read-only: `native.summary` and `native.notifications` only.
    case widget
}

protocol TokenProviding: Sendable {
    func token(_ kind: TokenKind) -> String?
}

protocol TokenStoring: TokenProviding {
    /// `nil` deletes the token.
    func setToken(_ value: String?, for kind: TokenKind) throws
}

/// In-memory tokens for previews and tests.
final class StaticTokens: TokenStoring, @unchecked Sendable {
    private let lock = NSLock()
    private var values: [TokenKind: String]
    init(_ values: [TokenKind: String] = [:]) { self.values = values }
    func token(_ kind: TokenKind) -> String? { lock.withLock { values[kind] } }
    func setToken(_ value: String?, for kind: TokenKind) throws { lock.withLock { values[kind] = value } }
}

// MARK: - Transport

/// Network seam so the client and SSE stream can be tested with a fake.
protocol HTTPTransport: Sendable {
    func data(for request: URLRequest) async throws -> (Data, HTTPURLResponse)
    /// Streams the response body line by line (without the trailing newline). Used for SSE.
    func lines(for request: URLRequest) async throws -> (AsyncThrowingStream<String, Error>, HTTPURLResponse)
}

enum DroverError: Error, Sendable, Equatable {
    case notConfigured
    case missingToken(TokenKind)
    case unauthorized
    case http(Int)
    case server(String)
    case decoding(String)
    case transport(String)

    /// Sentence case, no em dashes, never includes a token or URL query.
    var userMessage: String {
        switch self {
        case .notConfigured: "Set the server address in Settings."
        case .missingToken(.widget): "Add a widget or main token in Settings."
        case .missingToken(.main): "This needs the main token. Add it in Settings."
        case .unauthorized: "The server rejected the token."
        case .http(let code): "The server answered with HTTP \(code)."
        case .server(let message): message
        case .decoding: "The server sent something this app does not understand."
        case .transport(let message): message
        }
    }
}

// MARK: - Connection and badge

enum ConnectionState: Sendable, Equatable {
    /// No server URL or no token at all.
    case unconfigured
    case connecting
    /// Polling `native.summary` with the widget token (or the main token while SSE is down).
    case polling
    /// SSE connected with the main token; summary refreshed on events.
    case live
    case offline(String)
    case unauthorized
}

enum BadgeTone: String, Sendable {
    case waiting, working, idle, error, unconfigured
}

/// What the menu bar icon shows. Pure, so it is unit tested.
struct BadgeState: Sendable, Equatable {
    var count: Int
    var tone: BadgeTone
    var accessibilityLabel: String

    init(summary: Summary?, connection: ConnectionState) {
        switch connection {
        case .unconfigured:
            self.init(count: 0, tone: .unconfigured, label: "Drover, not set up")
            return
        case .unauthorized:
            self.init(count: 0, tone: .error, label: "Drover, token rejected")
            return
        case .offline where summary == nil:
            self.init(count: 0, tone: .error, label: "Drover, offline")
            return
        default: break
        }
        guard let summary else {
            self.init(count: 0, tone: .idle, label: "Drover, loading")
            return
        }
        let waiting = summary.totals.waiting
        let working = summary.totals.working
        if case .offline = connection {
            self.init(count: waiting, tone: .error, label: "Drover, offline, \(waiting) waiting when last seen")
        } else if waiting > 0 {
            self.init(count: waiting, tone: .waiting, label: "Drover, \(waiting) waiting on you")
        } else if working > 0 {
            self.init(count: 0, tone: .working, label: "Drover, \(working) working")
        } else {
            self.init(count: 0, tone: .idle, label: "Drover, all idle")
        }
    }

    init(count: Int, tone: BadgeTone, label: String) {
        self.count = count
        self.tone = tone
        self.accessibilityLabel = label
    }
}

// MARK: - Preferences

enum OpenTarget: String, Codable, Sendable, CaseIterable {
    /// The native macOS app when installed, else the web UI.
    case mainAppThenWeb
    case webUI
}

/// A global shortcut. `keyCode` is a Carbon virtual key code (kVK_*); display and Carbon conversion
/// live in Hotkey/KeyCombo+Format.swift.
struct KeyCombo: Codable, Sendable, Hashable {
    struct Modifiers: OptionSet, Codable, Sendable, Hashable {
        let rawValue: UInt32
        init(rawValue: UInt32) { self.rawValue = rawValue }
        static let command = Modifiers(rawValue: 1 << 0)
        static let option = Modifiers(rawValue: 1 << 1)
        static let control = Modifiers(rawValue: 1 << 2)
        static let shift = Modifiers(rawValue: 1 << 3)
    }

    var keyCode: UInt32
    var modifiers: Modifiers

    /// Control-Option-A.
    static let defaultCombo = KeyCombo(keyCode: 0x00, modifiers: [.control, .option])
}

struct MenuBarPreferences: Codable, Sendable, Equatable {
    var serverURL: String = "http://127.0.0.1:7337"
    /// Poll interval for `native.summary`; clamped to `pollRange`.
    var pollSeconds: Int = 60
    var openTarget: OpenTarget = .mainAppThenWeb
    var notifyOnWaiting: Bool = true
    var notificationSound: Bool = true
    /// `nil` disables the global shortcut.
    var hotkey: KeyCombo? = .defaultCombo

    static let `default` = MenuBarPreferences()
    static let pollRange = 15...900

    /// A usable http(s) base URL without query, fragment or credentials, else nil. Plain http is
    /// only accepted where App Transport Security allows it (`NSAllowsLocalNetworking`): loopback,
    /// IP literals, `.local` and single-label names. Other names (e.g. `*.ts.net`) need https.
    var baseURL: URL? {
        let trimmed = serverURL.trimmingCharacters(in: .whitespacesAndNewlines)
        guard var c = URLComponents(string: trimmed),
              let scheme = c.scheme?.lowercased(), scheme == "http" || scheme == "https",
              let host = c.host, !host.isEmpty,
              c.user == nil, c.password == nil, c.query == nil, c.fragment == nil
        else { return nil }
        if scheme == "http", !Self.allowsPlainHTTP(host: host) { return nil }
        if c.path.hasSuffix("/") { c.path = String(c.path.dropLast()) }
        return c.url
    }

    static func allowsPlainHTTP(host: String) -> Bool {
        let h = host.lowercased().trimmingCharacters(in: CharacterSet(charactersIn: "[]"))
        if h == "localhost" || h.hasSuffix(".local") || !h.contains(".") { return true }
        let isIPv4 = h.split(separator: ".", omittingEmptySubsequences: false).count == 4
            && h.allSatisfy { $0.isNumber || $0 == "." }
        let isIPv6 = h.contains(":")
        return isIPv4 || isIPv6
    }

    var clampedPollSeconds: Int {
        min(max(pollSeconds, Self.pollRange.lowerBound), Self.pollRange.upperBound)
    }
}

// MARK: - Links

/// Where "Open" and "Open dashboard" go. Never puts a token in a URL.
enum Links {
    /// `drover://session/<id>?host=<host>` (CONTRACT.md URL scheme), opened by the macOS app.
    static func appSession(_ id: String, host: String) -> URL {
        var c = URLComponents()
        c.scheme = AppIdentifiers.urlScheme
        c.host = "session"
        c.path = "/" + id
        if !host.isEmpty, host != "local" { c.queryItems = [URLQueryItem(name: "host", value: host)] }
        return c.url!
    }

    static let appBoard = URL(string: "drover://board")!
    static let appManager = URL(string: "drover://manager")!

    /// The web UI's Manager view.
    static func webManager(base: URL) -> URL {
        URL(string: base.absoluteString + "/#/manager")!
    }

    /// The web UI's pop-out drawer route: `#/pop/session/<host>/<id>/<engine>/<name>`.
    static func webSession(base: URL, id: String, host: String, engine: String, name: String) -> URL {
        let segs = ["pop", "session", host.isEmpty ? "local" : host, id, engine, name].map(encodeSegment)
        return URL(string: base.absoluteString + "/#/" + segs.joined(separator: "/"))!
    }

    static func webBoard(base: URL) -> URL {
        URL(string: base.absoluteString + "/#/board")!
    }

    private static func encodeSegment(_ s: String) -> String {
        var allowed = CharacterSet.alphanumerics
        allowed.insert(charactersIn: "-._~")
        return s.addingPercentEncoding(withAllowedCharacters: allowed) ?? s
    }
}

/// One click is one deep link: the same URL again within `window` seconds (a double click, a notification
/// action racing the popover) is dropped, so the app gets one activation and one URL event.
struct OpenThrottle: Sendable {
    var window: TimeInterval = 1
    private var last: (url: URL, at: Date)?

    init(window: TimeInterval = 1) { self.window = window }

    mutating func allow(_ url: URL, now: Date = Date()) -> Bool {
        if let last, last.url == url, now.timeIntervalSince(last.at) < window { return false }
        last = (url, now)
        return true
    }
}

